const validateEmail = (req, res, next) => {
  const { email } = req.query;
  if (email && !validator.isEmail(email)) {
    return res.status(400).json({ error: 'Invalid email format' });
  }
  next();
};

// Validate MongoDB ObjectId format if present
const validateIdParam = (req, res, next) => {
  const { id } = req.params;
  if (id && !validator.isMongoId(id)) {
    return res.status(400).json({ error: 'Invalid ID format' });
  }
  next();
};

module.exports = { validateEmail, validateIdParam };

// Centralized error handling middleware

// Handle 404 for undefined routes
const notFound = (req, res, next) => {
  const error = new Error(`Not Found - ${req.originalUrl}`);
  res.status(404);
  next(error);
};

// Central error handler
const errorHandler = (err, req, res, next) => {
  // Log the error stack (in production, use a logging service)
  console.error(err.stack);

  // Set default status code if not already set
  const statusCode = res.statusCode === 200 ? 500 : res.statusCode;

  // Prevent stack trace leakage in production
  res.status(statusCode).json({
    message: err.message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
};

module.exports = { notFound, errorHandler };

