require('dotenv').config({ path: '.env.test' });

const { Client } = require('pg');
const https = require('https');

// 1. Test Database Connection
async function testDatabase() {
  const client = new Client({
    connectionString: process.env.DATABASE_URL,
  });

  try {
    await client.connect();
    const res = await client.query('SELECT NOW()');
    console.log('✅ Database connected:', res.rows[0]);
    return true;
  } catch (err) {
    console.error('❌ Database connection failed:', err.message);
    return false;
  } finally {
    await client.end();
  }
}

// 2. Test Anthropic API Key
function testAnthropic() {
  return new Promise((resolve) => {
    const options = {
      hostname: 'api.anthropic.com',
      port: 443,
      path: '/v1/complete',
      method: 'POST',
      headers: {
        'x-api-key': process.env.ANTHROPIC_API_KEY,
        'content-type': 'application/json',
        'anthropic-version': '2023-06-01',
      },
    };

    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => (data += chunk));
      res.on('end', () => {
        if (res.statusCode === 401) {
          console.log('❌ Anthropic API key invalid:', data);
          resolve(false);
        } else {
          console.log('✅ Anthropic API key accepted (status:', res.statusCode, ')');
          resolve(true);
        }
      });
    });

    req.on('error', (error) => {
      console.error('❌ Anthropic request failed:', error.message);
      resolve(false);
    });

    req.write(JSON.stringify({
      model: 'claude-2.1',
      prompt: '\n\nHuman: say hello\n\nAssistant:',
      max_tokens_to_sample: 10,
    }));
    req.end();
  });
}

// 3. Test Stripe API Key
function testStripe() {
  return new Promise((resolve) => {
    const options = {
      hostname: 'api.stripe.com',
      port: 443,
      path: '/v1/account',
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${process.env.STRIPE_SECRET_KEY}`,
      },
    };

    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => (data += chunk));
      res.on('end', () => {
        if (res.statusCode === 200) {
          console.log('✅ Stripe key valid. Account:', JSON.parse(data).business_name);
          resolve(true);
        } else {
          console.log('❌ Stripe key invalid:', data);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.error('❌ Stripe request failed:', error.message);
      resolve(false);
    });

    req.end();
  });
}

// 4. Test AWS Credentials via STS (limited scope)
function testAWS() {
  return new Promise((resolve) => {
    const options = {
      hostname: 'sts.amazonaws.com',
      port: 443,
      path: '/?Action=GetCallerIdentity&Version=2011-06-15',
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
      },
    };

    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => (data += chunk));
      res.on('end', () => {
        if (res.statusCode === 403) {
          console.log('✅ AWS key exists but access denied (expected for STS without SigV4)');
          resolve(true); // Key exists even if not authorized
        } else {
          console.log('❌ AWS unexpected response:', res.statusCode, data);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      // Connection errors might mean network policy blocks AWS
      console.error('⚠️  AWS connectivity issue:', error.message);
      resolve(false);
    });

    req.write(`Action=GetCallerIdentity&Version=2011-06-15`);
    req.end();
  });
}

// 5. Test Logfire Token
function testLogfire() {
  return new Promise((resolve) => {
    const options = {
      hostname: 'api.logfire.io',
      port: 443,
      path: '/v1/health',
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${process.env.LOGFIRE_TOKEN}`,
      },
    };

    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => (data += chunk));
      res.on('end', () => {
        if (res.statusCode === 200) {
          console.log('✅ Logfire token valid:', data);
          resolve(true);
        } else {
          console.log('❌ Logfire token invalid:', data);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.error('❌ Logfire request failed:', error.message);
      resolve(false);
    });

    req.end();
  });
}

// Run all tests
async function main() {
  console.log('🔍 Verifying credentials from .env.test...\n');
  const results = {};

  results.database = await testDatabase();
  results.anthropic = await testAnthropic();
  results.stripe = await testStripe();
  results.aws = await testAWS();
  results.logfire = await testLogfire();

  console.log('\n📊 Summary:');
  Object.entries(results).forEach(([service, ok]) => {
    console.log(`${ok ? '✅' : '❌'} ${service.charAt(0).toUpperCase() + service.slice(1)}`);
  });

  const validCount = Object.values(results).filter(Boolean).length;
  console.log(`\n${validCount}/${Object.keys(results).length} credentials are reachable.`);
}

main().catch(console.error);

