  // Validate query parameters if any
  (req, res, next) => {
    // Simple validation - if any query params are provided, they should be allowed ones
    const allowedParams = ['format', 'detailed'];
    const invalidParams = Object.keys(req.query).filter(param => !allowedParams.includes(param));

    if (invalidParams.length > 0) {
      return res.status(400).json({
        error: `Invalid query parameters: ${invalidParams.join(', ')}`,
        code: 'INVALID_PARAMETERS'
      });
    }
    next();
  }
], (req, res) => {
