  // Results should be sanitized before sending
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Sanitize user data (remove sensitive fields if present)
  const sanitizedUsers = users.map(({ id, name, email }) => ({ id, name, email }));

  res.json(sanitizedUsers);
});

// Users endpoint - POST (example of input validation)
app.post('/users', validateUser, (req, res) => {
  // Check for validation errors
